  "taxGuide.switzerland.goods.personal": "Switzerland: Purchases must be for personal or gift use rather than resale or business inventory.",
  "taxGuide.switzerland.goods.unused": "Switzerland: Do not consume, wear or otherwise use goods before customs has had the opportunity to inspect them.",
  "taxGuide.switzerland.minimumExplanation": "Switzerland: The minimum-purchase display comes from the shared calculator rule, including its gross Swiss-invoice basis and inclusive comparison.",
  "taxGuide.switzerland.operatorFeeExplanation": "Switzerland: Retailer and operator procedures determine fees, payout timing and the net refund received.",
  "taxGuide.switzerland.refund.method.card": "Switzerland: Card refund when selected and supported by the retailer or refund operator.",
  "taxGuide.switzerland.refund.method.cash": "Switzerland: Cash refund only at available authorised counters after validation.",
  "taxGuide.switzerland.refund.method.transfer": "Switzerland: Bank transfer when offered by the retailer or refund operator.",
  "taxGuide.switzerland.source.customsValidation": "Switzerland — Official customs validation and export-confirmation procedure.",
  "taxGuide.switzerland.source.goodsConditions": "Switzerland — Official conditions for baggage export, personal goods and exclusions.",
  "taxGuide.switzerland.source.schemeMinimum": "Switzerland — Official eligibility, purchase-threshold and document requirements.",
  "taxGuide.switzerland.source.vatRate": "Switzerland — Official standard VAT rate reference.",
  "taxGuide.switzerland.step.beforeDeparture.checkedBags": "Switzerland: If goods will be checked in, complete customs steps before bag drop because inspection can be required.",
  "taxGuide.switzerland.step.beforeDeparture.deadline": "Switzerland: Prepare the Swiss export document, goods and travel evidence before departure so export confirmation fits the official Swiss deadline.",
  "taxGuide.switzerland.step.beforeDeparture.swissExit": "Switzerland: Prepare Swiss export validation when leaving Switzerland with the goods.",
  "taxGuide.switzerland.step.beforeShopping.goods": "Switzerland: Plan packing and connections so the goods can be shown at customs before export.",
  "taxGuide.switzerland.step.beforeShopping.residence": "Switzerland: Confirm that your residence status qualifies before relying on nationality alone.",
  "taxGuide.switzerland.step.beforeShopping.retailer": "Switzerland: Use a participating retailer that can issue the required national refund documentation.",
  "taxGuide.switzerland.step.customs.desk": "Switzerland: Use the Swiss customs desk when inspection or manual confirmation is required.",
  "taxGuide.switzerland.step.customs.present": "Switzerland: Be ready to present goods, passport, Swiss export document, receipts and travel evidence.",
  "taxGuide.switzerland.step.customs.swissCustoms": "Switzerland: Use the Swiss customs export-confirmation procedure or accepted digital confirmation route.",
  "taxGuide.switzerland.step.inStore.check": "Switzerland: Review name, document number, residence, purchase and refund details before leaving the store.",
  "taxGuide.switzerland.step.inStore.exportDocument": "Switzerland: Ask the retailer for the Swiss export document required for the refund procedure.",
  "taxGuide.switzerland.step.inStore.identity": "Switzerland: Show passport and residence evidence requested by the retailer before the document is issued.",
  "taxGuide.switzerland.step.inStore.keep": "Switzerland: Keep the refund document, receipts, travel evidence and goods together until validation is complete.",
  "taxGuide.switzerland.step.refund.afterValidation": "Switzerland: Refund processing starts only after customs validation or accepted export confirmation is recorded.",
  "taxGuide.switzerland.step.refund.fees": "Switzerland: Operator charges, payment fees and exchange rates can reduce the final amount received.",
  "taxGuide.switzerland.step.refund.methods": "Switzerland: Card, cash or bank-transfer availability depends on the retailer, refund operator and departure location.",
  "taxGuide.switzerland.vatExplanation": "Switzerland: The statutory VAT rate is reference data from the shared rule layer; it is not the expected refund amount.",
  "taxGuide.switzerland.warning.checkedBaggage": "Switzerland: Do not check goods before the customs inspection opportunity has passed.",
  "taxGuide.switzerland.warning.customsNotPayment": "Switzerland: Customs confirmation proves export but does not itself make the payment.",
  "taxGuide.switzerland.warning.nonEuProcess": "Switzerland is outside the EU; use the Swiss procedure rather than EU final-exit validation.",
  "taxGuide.switzerland.warning.operatorTiming": "Switzerland: Retailer and refund-operator processing times can differ by payment route.",
  "taxGuide.switzerland.warning.validationRequired": "Switzerland: Without customs validation or accepted export confirmation, the refund may be refused.",
