  "taxGuide.czech-republic.refund.method.transfer": "Bank transfer requires valid account details and provider acceptance after customs confirmation.",
  "taxGuide.czech-republic.warning.validationRequired": "A document without customs confirmation is not enough for payment.",
  "taxGuide.czech-republic.warning.checkedBaggage": "Goods packed in checked baggage should be shown to customs before bag drop if inspection is required.",
