  "taxGuide.finland.step.beforeDeparture.route": "Plan the correct departure route and validation location. The ordinary traveller sale is for buyers not established in the EU or Norway, using habitual residence and permanent address evidence. The participating retailer or authorised refund business records passport, residence, detailed receipt, itemised goods, price and refund details, seals the package, and the unused goods and intact seal are inspected by Customs or the authorised desk. Export is in personal luggage within the official three-month period; final EU exit may be Finland or another member state, with Customs fallback if the authorised desk is unavailable. Permanent residents of Norway use a separate immediate-transport and Norwegian import-VAT proof route.",
