  "taxGuide.sweden.document.goods": "Goods available for inspection. The traveller must live outside the EU, or meet the official move-from-Sweden rule and intend to live outside the EU for the required period. Goods are bought and carried by the traveller, unused, for non-commercial personal use, and covered by a participating retailer Tax Free receipt plus shop receipt, passport and travel documents. Swedish Customs currently says Sweden must be the last country visited before leaving the EU for this procedure. Tax Free partners handle partner documents and payment in Sweden; Swedish Customs handles fallback validation when the partner is closed, and validation is not payment.",
