  "taxGuide.norway.document.receipts": "Proof of purchase records. Norway is not an EU procedure. The traveller must be resident abroad and agree refund eligibility with the retailer because Norwegian Customs does not pay refunds. Official thresholds and proof routes depend on residence: residents of Sweden, Denmark and Finland use an import-VAT proof procedure, other residents use an invoice-based route, and Svalbard and Jan Mayen have separate treatment. Route one uses retailer form RD-0032 E, personal presentation of form and goods at a staffed customs location within one month after delivery, no retrospective attestation after departure, and retailer payment after the attested form is returned. Route two uses a private Tax-Free Shopping undertaking document that must not be stamped by Norwegian Customs; operator conditions and fees may apply.",
