  "taxGuide.ireland.warning.validationRequired": "No refund should be expected without valid export evidence. The Retail Export Scheme is for tourists or travellers resident outside the EU; Northern Ireland residents are excluded and Great Britain residents may qualify with current proof. The retailer charges tax, issues an export voucher, obtains residence evidence, inbound and outbound travel dates and a signed traveller declaration, and refunds directly or through a refund agent after proof of export. Goods are for private use, exported in personal luggage by the last day of the third month after supply, kept available for Customs inspection, and services are excluded. Ordinary non-high-value goods may receive Irish certification even when Ireland is not the final EU departure if official ticket and deadline conditions are met. High-value goods require direct Customs Officer presentation; drop boxes or refund-agent submission are insufficient, with final-EU-exit and short-transit rules applied as Revenue describes.",
